async function getHints(){try{const t=await fetch("/hints.json");if(!t.ok)throw new Error(`Response status: ${t.status}`);return await t.json()}catch(t){console.error(t.message)}}async function runHints(){let t=await getHints();tippy("*[hint]",{content:n=>t[n.getAttribute("hint")],allowHTML:!0,placement:"bottom"})}document.getElementsByClassName("hint").length>0&&runHints();